options.customCss:
:root {
  --chat--color-primary: #006699;
  --chat--color-primary-shade-50: #005580;
  --chat--color-primary-shade-100: #004466;
  --chat--color-secondary: #00a8cc;
  --chat--color-white: #ffffff;
  --chat--color-light: #f0f7fa;
  --chat--color-dark: #102a43;
  --chat--border-radius: 16px;
  --chat--header--background: linear-gradient(135deg, #003366 0%, #0077b6 100%);
  --chat--header--color: #ffffff;
  --chat--message--bot--background: #ffffff;
  --chat--message--bot--color: #102a43;
  --chat--message--user--background: #0077b6;
  --chat--message--user--color: #ffffff;
  --chat--body--background: #e6f2f8;
}

/* Centraliza e dá aspecto de aplicativo ao container no navegador */
.chat-window-wrapper,
#n8n-chat {
  font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}

/* Sombra suave nos balões do bot */
.chat-message-from-bot {
  box-shadow: 0 2px 6px rgba(0, 51, 102, 0.08);
  border: 1px solid #d0e4f0;
}

/* Destaque no botão de enviar */
.chat-input-send-button {
  background-color: #0077b6 !important;
  border-radius: 50% !important;
  transition: transform 0.15s ease;
}

.chat-input-send-button:hover {
  transform: scale(1.06);
}

